import React, { useState } from 'react';

const LoginUser = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');  // State untuk email
  const [errorMessage, setErrorMessage] = useState('');

  const handleLogin = (e) => {
    e.preventDefault();

    // Simulasi validasi login
    if (username === 'user' && password === 'password') {
      alert('Login berhasil!');
      setErrorMessage('');
    } else {
      setErrorMessage('Anda belum mendaftar. Silakan buat akun terlebih dahulu.');
    }
  };

  return (
    <div
      style={{
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        height: '100vh',
        background: 'linear-gradient(to bottom, #a2c2e8, #f0f8ff)', // Gradasi biru dan abu muda
      }}
    >
      <div
        style={{
          width: '400px',  // Lebih lebar dibandingkan sebelumnya
          padding: '30px', // Tambahkan padding untuk ruang lebih
          borderRadius: '10px',
          boxShadow: '0px 8px 16px rgba(0, 0, 0, 0.1)',
          backgroundColor: '#ffffff',
        }}
      >
      <h1 style={{ textAlign: 'center', marginBottom: '10px', fontSize: '24px' }}>Login Pengguna</h1>
        <p style={{ textAlign: 'center', fontSize: '16px', marginBottom: '30px', color: '#555' }}>
          Isi data diri anda dengan benar!
        </p>
        <form onSubmit={handleLogin}>
          <div style={{ marginBottom: '20px' }}>
            <label htmlFor="email" style={{ display: 'block', marginBottom: '8px', fontSize: '16px' }}>
              Email:
            </label>
            <input
              type="email"
              id="email"
              name="email"
              autoComplete="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                borderRadius: '6px',
                border: '1px solid #ccc',
                fontSize: '16px',
                boxSizing: 'border-box',
              }}
              required
            />
          </div>
          <div style={{ marginBottom: '20px' }}>
            <label htmlFor="password" style={{ display: 'block', marginBottom: '8px', fontSize: '16px' }}>
              Kata Sandi:
            </label>
            <input
              type="password"
              id="password"
              name="password"
              autoComplete="current-password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{
                width: '100%',
                padding: '12px',
                borderRadius: '6px',
                border: '1px solid #ccc',
                fontSize: '16px',
                boxSizing: 'border-box',
              }}
              required
            />
          </div>
          <button
            type="submit"
            style={{
              width: '100%',
              padding: '14px',
              borderRadius: '6px',
              border: 'none',
              backgroundColor: '#007bff',
              color: '#fff',
              fontWeight: 'bold',
              fontSize: '16px',
              cursor: 'pointer',
              transition: 'background-color 0.3s',
            }}
            onMouseOver={(e) => e.target.style.backgroundColor = '#0056b3'}
            onMouseOut={(e) => e.target.style.backgroundColor = '#007bff'}
          >
            Kirim
          </button>
        </form>
        {errorMessage && (
          <p
            style={{
              marginTop: '20px',
              color: 'red',
              textAlign: 'center',
              fontSize: '14px',
            }}
          >
            {errorMessage}
          </p>
        )}
      </div>
    </div>
  );
};

export default LoginUser;
